import subprocess

def get(path):
    out = subprocess.run(['git','show', f'origin/main:{path}'], capture_output=True, text=True).stdout
    return out

files = subprocess.run(['git','ls-tree','-r','origin/main','--name-only'], capture_output=True, text=True).stdout.splitlines()
files = [f for f in files if f.endswith('VERSIONS.md')]

def vkey(v):
    parts = v.split('.')
    try:
        return tuple(int(p) for p in parts)
    except:
        return None

bad = []
for f in files:
    content = get(f)
    vers = []
    for line in content.splitlines():
        if line.startswith('| ') and not line.startswith('|---'):
            cols = [c.strip() for c in line.split('|')]
            if len(cols) > 1 and cols[1] and cols[1] != 'Version':
                vers.append(cols[1])
    keys = [vkey(v) for v in vers]
    if None in keys:
        continue
    if keys != sorted(keys, reverse=True):
        bad.append((f, vers))

for f, vers in bad:
    print(f)
    print(vers)
print('total files', len(files), 'bad', len(bad))
"

